insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-001', '1.2-becoming-a-permanent-resident', 'How many questions are there in the Life in the UK test?', '["18","24","30","45"]'::jsonb, '[1]'::jsonb, false, '1.4: ''The test consists of 24 questions about important aspects of life in the UK.''', 1) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-002', '1.2-becoming-a-permanent-resident', 'What level of English does the Life in the UK test assume?', '["ESOL Entry Level 1","ESOL Entry Level 3","GCSE English","IELTS Band 7"]'::jsonb, '[1]'::jsonb, false, '1.2: ''The questions are written in a way that requires an understanding of the English language at ESOL Entry Level 3.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-003', '1.2-becoming-a-permanent-resident', 'From October 2013, what evidence must you produce alongside passing the Life in the UK test for settlement or permanent residence?', '["A university degree certificate","Evidence of speaking and listening skills in English at B1 of the Common European Framework of Reference","A letter from your employer","Proof of home ownership"]'::jsonb, '[1]'::jsonb, false, '1.2: ''Produce acceptable evidence of speaking and listening skills in English at B1 of the Common European Framework of Reference. This is equivalent to ESOL Entry Level 3.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-004', '1.2-becoming-a-permanent-resident', 'Select TWO things you need to apply to become a permanent resident or citizen of the UK.', '["Speak and read English","Own a property in the UK","Have a good understanding of life in the UK","Hold a university degree"]'::jsonb, '[0,2]'::jsonb, true, '1.2: ''To apply to become a permanent resident or citizen of the UK, you will need to: speak and read English; have a good understanding of life in the UK.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-005', '1.2-becoming-a-permanent-resident', 'What is the alternative to taking the Life in the UK test if your English is below ESOL Entry Level 3?', '["You cannot become a permanent resident","Pass an ESOL course in English with Citizenship","Pay an additional fee instead","Take the test in your native language"]'::jsonb, '[1]'::jsonb, false, '1.2: ''Pass an ESOL course in English with Citizenship. You will need to take this course if your standard of English is below ESOL Entry Level 3.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-006', '1.2-becoming-a-permanent-resident', 'Passing the Life in the UK test is part of demonstrating what?', '["A good understanding of life in the UK when applying for permanent residence or citizenship","Your English writing skills","Your knowledge of British sport","Your right to work in the UK"]'::jsonb, '[0]'::jsonb, false, '1.2: ''To apply to become a permanent resident or citizen of the UK, you will need to: speak and read English; have a good understanding of life in the UK.''', 1) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-007', '1.2-becoming-a-permanent-resident', 'Evidence of speaking and listening skills in English at B1 of the Common European Framework of Reference is equivalent to which ESOL level?', '["ESOL Entry Level 3","ESOL Entry Level 1","ESOL Entry Level 2","GCSE English"]'::jsonb, '[0]'::jsonb, false, '1.2: ''Produce acceptable evidence of speaking and listening skills in English at B1 of the Common European Framework of Reference. This is equivalent to ESOL Entry Level 3.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.2-008', '1.2-becoming-a-permanent-resident', 'Select TWO things applicants for permanent residence or citizenship have needed to do since October 2013.', '["Pass the Life in the UK test","Hold a British university degree","Produce acceptable evidence of English speaking and listening skills at B1","Provide a letter from an employer"]'::jsonb, '[0,2]'::jsonb, true, '1.2: ''From October 2013, the requirement is to: pass the Life in the UK test AND produce acceptable evidence of speaking and listening skills in English at B1 of the Common European Framework of Reference.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-001', '1.3-values-and-principles', 'Which of these is one of the fundamental principles of British life listed in the handbook?', '["Monarchy by divine right","The rule of law","State religion","One-party rule"]'::jsonb, '[1]'::jsonb, false, '1.3: ''The fundamental principles of British life include: Democracy, The rule of law, Individual liberty, Tolerance of those with different faiths and beliefs, Participation in community life.''', 1) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-002', '1.3-values-and-principles', 'Select TWO things the UK offers in return for residents respecting and obeying the law.', '["Freedom of belief and religion","Automatic citizenship after one year","A right to a fair trial","Free university tuition"]'::jsonb, '[0,2]'::jsonb, true, '1.3: ''In return, the UK offers: freedom of belief and religion, freedom of speech, freedom from unfair discrimination, a right to a fair trial, a right to join in the election of a government.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-003', '1.3-values-and-principles', 'As part of the citizenship ceremony, new citizens pledge to do what?', '["Renounce all other nationalities","Uphold the UK''s democratic values and observe its laws faithfully","Join a political party","Learn Welsh, Gaelic and Irish"]'::jsonb, '[1]'::jsonb, false, '1.3: ''I will give my loyalty to the United Kingdom and respect its rights and freedoms. I will uphold its democratic values. I will observe its laws faithfully and fulfil my duties and obligations as a British citizen.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-004', '1.3-values-and-principles', 'According to the handbook, is there a place in British society for extremism or intolerance?', '["Yes, as long as it is non-violent","No, there is no place for it","Only during elections","Only in private settings"]'::jsonb, '[1]'::jsonb, false, '1.3: ''There is no place in British society for extremism or intolerance.''', 1) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-005', '1.3-values-and-principles', 'In return for respecting the laws and values of the UK, which freedom does the UK offer?', '["Freedom of speech","Free housing","Guaranteed employment","Exemption from taxes"]'::jsonb, '[0]'::jsonb, false, '1.3: ''In return, the UK offers: freedom of belief and religion, freedom of speech, freedom from unfair discrimination, a right to a fair trial, a right to join in the election of a government.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-006', '1.3-values-and-principles', 'The fundamental principles of British life include democracy, the rule of law, individual liberty, tolerance of those with different faiths and beliefs, and what else?', '["Participation in community life","Compulsory voting","Military service","Church attendance"]'::jsonb, '[0]'::jsonb, false, '1.3: ''The fundamental principles of British life include: Democracy, The rule of law, Individual liberty, Tolerance of those with different faiths and beliefs, Participation in community life.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-007', '1.3-values-and-principles', 'Select TWO of the fundamental principles of British life.', '["Individual liberty","Compulsory military service","Tolerance of those with different faiths and beliefs","State ownership of industry"]'::jsonb, '[0,2]'::jsonb, true, '1.3: ''The fundamental principles of British life include: Democracy, The rule of law, Individual liberty, Tolerance of those with different faiths and beliefs, Participation in community life.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.3-008', '1.3-values-and-principles', 'The responsibilities of those living in the UK include looking after yourself and your family, and looking after what else?', '["The area in which you live and the environment","Your neighbours'' finances","Local businesses","National monuments"]'::jsonb, '[0]'::jsonb, false, '1.3: ''If you wish to be a permanent resident or citizen of the UK, you should: respect and obey the law; respect the rights of others, including their right to their own opinions; treat others with fairness; look after yourself and your family; look after the area in which you live and the environment.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.4-001', '1.4-taking-the-test', 'In which languages, besides English, can special arrangements be made to take the Life in the UK test?', '["French and German","Welsh and Scottish Gaelic","Polish and Urdu","Irish Gaelic and Cornish"]'::jsonb, '[1]'::jsonb, false, '1.4: ''The Life in the UK test is usually taken in English, although special arrangements can be made if you wish to take it in Welsh or Scottish Gaelic.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.4-002', '1.4-taking-the-test', 'True or false: you can take the Life in the UK test at any test centre of your choosing, including ones not registered with the UK Border Agency.', '["True","False"]'::jsonb, '[1]'::jsonb, false, '1.4: ''You should not take your test at any other establishment as the UK Border Agency will only accept certificates from registered test centres.''', 2) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
insert into questions (id, subsection_id, question, options, correct_answers, multi_select, source_fact, difficulty) values ('q-1.4-003', '1.4-taking-the-test', 'Approximately how many registered test centres are there around the UK for taking the Life in the UK test?', '["About 10","About 60","About 200","About 500"]'::jsonb, '[1]'::jsonb, false, '1.4: ''You can only take the test at a registered and approved Life in the UK test centre... There are about 60 test centres around the UK.''', 3) on conflict (id) do update set subsection_id = excluded.subsection_id, question = excluded.question, options = excluded.options, correct_answers = excluded.correct_answers, multi_select = excluded.multi_select, source_fact = excluded.source_fact, difficulty = excluded.difficulty;
